import pytest
from django.core.files.uploadedfile import SimpleUploadedFile

from apps.accounts.tests.factories import StudentFactory
from apps.assessments.tests.factories import full_scores, load_example, make_forms
from apps.placements.tests.factories import ApprovedPlacementFactory, PeriodFactory

pytestmark = pytest.mark.django_db

PDF = b"%PDF-1.4\n" + b"0" * 128


def _pdf(name="report.pdf"):
    return SimpleUploadedFile(name, PDF, content_type="application/pdf")


def _scores_payload(form, ratio=1.0):
    return [{**item, "criterion": str(item["criterion"])} for item in full_scores(form, ratio)]


def test_coordinator_imports_and_reads_forms_by_role(auth_client, coordinator, student):
    period = PeriodFactory()
    data = {**load_example("example_workplace_form.json"), "period": str(period.id)}
    response = auth_client(coordinator).post(
        "/api/v1/assessment-forms/import/", data, format="json"
    )
    assert response.status_code == 201, response.content
    assert len(response.json()["criteria"]) == 7

    url = f"/api/v1/periods/{period.id}/assessment-forms/"
    assert len(auth_client(coordinator).get(url).json()) == 1
    assert len(auth_client(student).get(url).json()) == 1
    academic = ApprovedPlacementFactory(period=period).academic_supervisor
    assert auth_client(academic).get(url).json() == []  # not their role's form


def test_only_coordinators_manage_forms(auth_client, student, workplace_supervisor):
    period = PeriodFactory()
    data = {**load_example("example_workplace_form.json"), "period": str(period.id)}
    assert (
        auth_client(student)
        .post("/api/v1/assessment-forms/import/", data, format="json")
        .status_code
        == 403
    )
    url = f"/api/v1/periods/{period.id}/assessment-forms/"
    assert auth_client(workplace_supervisor).post(url, data, format="json").status_code == 403


def test_locked_form_returns_409_and_new_version_works(auth_client, coordinator):
    placement = ApprovedPlacementFactory()
    workplace, _ = make_forms(placement.period)
    client = auth_client(placement.workplace_supervisor)
    created = client.post(
        f"/api/v1/placements/{placement.id}/assessments/",
        {"form": str(workplace.id), "scores": []},
        format="json",
    )
    assert created.status_code == 201, created.content

    body = {**load_example("example_workplace_form.json")}
    body.pop("assessor_role", None)
    body["assessor_role"] = "WORKPLACE_SUPERVISOR"
    locked = auth_client(coordinator).put(
        f"/api/v1/assessment-forms/{workplace.id}/", body, format="json"
    )
    assert locked.status_code == 409
    assert locked.json()["code"] == "form_locked"

    clone = auth_client(coordinator).post(f"/api/v1/assessment-forms/{workplace.id}/new-version/")
    assert clone.status_code == 201
    assert clone.json()["version"] == workplace.version + 1


def test_supervisor_records_and_submits_an_assessment(auth_client):
    placement = ApprovedPlacementFactory()
    workplace, _ = make_forms(placement.period)
    client = auth_client(placement.workplace_supervisor)
    created = client.post(
        f"/api/v1/placements/{placement.id}/assessments/",
        {
            "form": str(workplace.id),
            "comment": "Strong intern.",
            "scores": _scores_payload(workplace),
        },
        format="json",
    )
    assert created.status_code == 201, created.content
    assessment_id = created.json()["id"]
    submitted = client.post(f"/api/v1/assessments/{assessment_id}/submit/")
    assert submitted.status_code == 200, submitted.content
    assert submitted.json()["status"] == "SUBMITTED"
    assert submitted.json()["percent"] == "100.00"
    locked = client.patch(f"/api/v1/assessments/{assessment_id}/", {"comment": "x"}, format="json")
    assert locked.status_code == 409


def test_students_cannot_assess_and_other_supervisors_get_404(auth_client):
    placement = ApprovedPlacementFactory()
    workplace, _ = make_forms(placement.period)
    url = f"/api/v1/placements/{placement.id}/assessments/"
    payload = {"form": str(workplace.id), "scores": []}
    assert auth_client(placement.student).post(url, payload, format="json").status_code == 403
    stranger = ApprovedPlacementFactory(period=placement.period).workplace_supervisor
    assert auth_client(stranger).post(url, payload, format="json").status_code == 404


def test_final_report_upload_review_and_download(auth_client):
    placement = ApprovedPlacementFactory()
    url = f"/api/v1/placements/{placement.id}/final-report/"
    student_client = auth_client(placement.student)

    uploaded = student_client.post(url, {"document": _pdf(), "title": "Final"}, format="multipart")
    assert uploaded.status_code == 201, uploaded.content
    report = uploaded.json()
    assert report["status"] == "SUBMITTED"

    academic_client = auth_client(placement.academic_supervisor)
    download = academic_client.get(report["download_url"])
    assert download.status_code == 200
    assert b"".join(download.streaming_content).startswith(b"%PDF")
    assert download["X-Content-Type-Options"] == "nosniff"

    assert student_client.post(f"/api/v1/final-reports/{report['id']}/accept/").status_code == 403
    returned = academic_client.post(
        f"/api/v1/final-reports/{report['id']}/return/",
        {"feedback": "Add references."},
        format="json",
    )
    assert returned.status_code == 200
    assert returned.json()["status"] == "RETURNED"
    assert student_client.get(url).json()["feedback"] == "Add references."


def test_final_report_files_are_private(auth_client):
    placement = ApprovedPlacementFactory()
    report = (
        auth_client(placement.student)
        .post(
            f"/api/v1/placements/{placement.id}/final-report/",
            {"document": _pdf()},
            format="multipart",
        )
        .json()
    )
    assert auth_client(StudentFactory()).get(report["download_url"]).status_code == 404
    assert (
        auth_client(placement.workplace_supervisor).get(report["download_url"]).status_code == 200
    )


def test_upload_rejects_a_renamed_executable(auth_client):
    placement = ApprovedPlacementFactory()
    fake = SimpleUploadedFile("evil.pdf", b"MZ\x90\x00" + b"0" * 64, content_type="application/pdf")
    response = auth_client(placement.student).post(
        f"/api/v1/placements/{placement.id}/final-report/", {"document": fake}, format="multipart"
    )
    assert response.status_code == 422
    assert response.json()["code"] == "bad_content"


def test_student_sees_the_result_only_after_finalize(auth_client, coordinator):
    placement = ApprovedPlacementFactory()
    workplace, academic = make_forms(placement.period)
    student_client = auth_client(placement.student)
    result_url = f"/api/v1/placements/{placement.id}/result/"
    assert student_client.get(result_url).status_code == 404

    for actor, form, ratio in (
        (placement.workplace_supervisor, workplace, 1.0),
        (placement.academic_supervisor, academic, 0.5),
    ):
        client = auth_client(actor)
        created = client.post(
            f"/api/v1/placements/{placement.id}/assessments/",
            {"form": str(form.id), "scores": _scores_payload(form, ratio)},
            format="json",
        )
        assert client.post(f"/api/v1/assessments/{created.json()['id']}/submit/").status_code == 200

    report = student_client.post(
        f"/api/v1/placements/{placement.id}/final-report/", {"document": _pdf()}, format="multipart"
    ).json()
    auth_client(placement.academic_supervisor).post(f"/api/v1/final-reports/{report['id']}/accept/")

    coordinator_client = auth_client(coordinator)
    preview = coordinator_client.get(result_url).json()
    assert preview["ready"] is True
    assert float(preview["total_percent"]) == 80.0

    assert student_client.post(f"/api/v1/placements/{placement.id}/finalize/").status_code == 403
    finalized = coordinator_client.post(f"/api/v1/placements/{placement.id}/finalize/")
    assert finalized.status_code == 201, finalized.content

    mine = student_client.get(result_url)
    assert mine.status_code == 200
    assert mine.json()["finalized"] is True
    assert mine.json()["grade"] == "A"
    assert len(student_client.get(f"/api/v1/placements/{placement.id}/assessments/").json()) == 2
